INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (325, 'Full body strength building program', 'full-body-strength-building-program', 'Full body strength gain', 2, 1, 12, 7, 100, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (326, 'Bodybuilding program', 'bodybuilding-program', 'My current bodybuilding program from which I''m having great results. The exercises are in such an order where you can superset them but as I workout in a commercial gym I''m not able to. Also addd in leg extensions, i couldn’t find the exercise and can’t create them as i already hit the max created. The only exercises i never change are the first ones of each muscle group other than that i usually do different variations when i feel like it.', 4, 2, 12, 8, 150, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (327, 'Hypertrophy PPL', 'hypertrophy-ppl', 'High Volume PPL 6x/week program focused on Hypertrophy. Every major muscle is hit 10+ times per week. Forearms and calves are done daily. Every set is close to failure excluding your warmup sets / stretching etc... This is not a strength program. Not recommended for athletes in-season.', 8, 2, 16, 6, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (328, 'SLEEPER PHYSIQUE(BEAST-MODE)', 'sleeper-physiquebeast-mode', 'To look lean and shredded at same time strong', 4, 2, 18, 4, 10, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (329, 'AESTHETIC BEAST: The Laid Split', 'aesthetic-beast-the-laid-split', 'This program is built for guys chasing the most elite aesthetic physique possible—broad shoulders, full chest, wide lats, shredded arms, thick legs, and a powerful frame that looks sculpted, not bloated. Modeled directly after David Laid’s legendary Push/Pull/Legs training style, this 6-day-per-week split delivers maximum muscle growth and definition while maintaining lean lines and proportion. You’ll train like David: starting each day with heavy, compound lifts to build strength and size, then hammering in volume with pump-focused accessory work. Each muscle group gets hit 2x a week with smart exercise selection and intensity to carve in that “photoshoot-ready” look year-round. Whether you’re in a hoodie or shirtless at the beach, this program creates a physique that stuns. No unnecessary cardio, no nutrition micromanagement—just raw gym intensity, progressive overload, and an obsession with looking dangerous from every angle. Over time, you’ll build a frame that commands attention without saying a word: tall posture, lean mass, and aesthetic muscle that stands out everywhere. This is for those who want to be noticed, remembered, and respected. The Laid Split isn’t just training—it’s a transformation into a version of you that looks like he was built, not born.', 8, 2, 18, 6, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (330, 'Baki Mode', 'baki-mode', 'For the truest of gymcells, bodybuilding focused program, do as many reps as possible with a moderate amount of weight, choose a comfortable rep range and evolve.', 4, 1, 18, 6, 120, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (331, 'bodybuilding  4 day workout plan', 'bodybuilding-4-day-workout-plan', 'This is a begginer friendly program designed for more strength and achieving bigger muscles', 4, 3, 16, 7, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (332, 'Uncommon Among Most Uncommon Men !!!', 'uncommon-among-most-uncommon-men-', 'This is where we push past our limits .......................', 8, 2, 18, 7, 120, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (333, 'Gladiator Grind', 'gladiator-grind', 'Hybrid Home & Gym Workout Plan 2025', 4, 2, 10, 6, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (334, 'PPL x Arnold', 'ppl-x-arnold', 'The Arnold workout split is known for its high volume and frequency, focusing on building muscle mass and strength. Traditionally, it’s divided into body parts like chest/back, shoulders/arms, and legs. However, by combining it with an upper/lower body split, you can balance muscle recovery and training efficiency while still following Arnold’s principles.', 4, 2, 12, 7, 90, 1, 1, true, true, false, false);
