INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (337, 'Work Hard, Get Big', 'work-hard-get-big', 'Hypertrophy focused program, designed to be challenging, for intermediate to advanced lifters.  Will work best for those who are consistent, and dedicated.  110 to 130 seconds rest between sets.  First set is at heaviest weight, deep stretch for all exercises, 2 second controlled eccentric. Drop weight down if needed for follow up sets if needed to hit rep target.', 7, 2, 16, 7, 80, 1, 1, true, true, false, false);
