INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (339, 'Seventy Four Percent', 'seventy-four-percent', 'Just a tweaked version of RAVAGE.', 3, 1, 15, 6, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (340, 'Julian 2.0 Program', 'julian-20-program', 'This 16-week Legs-Push-Pull program is designed to build strength, muscle mass, and endurance through progressive overload and balanced training. By targeting all major muscle groups with a structured split, it ensures consistent gains while allowing optimal recovery. The alternating rep schemes promote continuous progression, helping you develop power, symmetry, and resilience. Whether you’re looking to increase strength, improve muscle definition, or build long-term fitness habits, this program provides the foundation for lasting results.', 4, 3, 16, 4, 60, 1, 1, true, true, false, false);
