INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (343, '6 Day Powerbuilding (Base+Peak)', '6-day-powerbuilding-basepeak', 'Introducing my 13-Week Powerbuilding Program: The ultimate training plan designed for serious lifters who want to build muscle, increase strength, and crush their 1-rep max on the bench press, squat, overhead press, and deadlift. Whether you''re aiming to improve your raw strength or build a physique that turns heads, this program combines the best of both worlds—powerlifting for maximal strength gains and bodybuilding for muscle growth and definition.', 2, 3, 13, 6, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (344, 'Basics Get You Big!!!', 'basics-get-you-big', 'This program is designed as a general size and strength program that will build a solid base of competence in the weight room. It is designed for early intermediates who want to get more serious about the gym. The program is designed to get you strong and proficient at all the basic lifts you’ll need to know no matter what your goal is later on, Bodybuilding, powerlifting, etc. The program uses linear progression to drive up your max on key lifts while getting you better at more fluff and pump stuff. If you eat right and sleep, this program will force your body to get jacked and strong.', 4, 1, 12, 6, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (345, 'Jin woo project', 'jin-woo-project', 'here is a program to gain strength and bodybuilding, the only equipment needed are 2 bags (to be used in dumbell and barbell), notebooks (to put in the bags) and a bar (if you have a real barbell use it, otherwise one simple bar or a katana for example). take 30 seconds of rest between reps and if it''s too difficult, lower the reps. Remember to stretch at the end of your workout to avoid the risk of injury. Good luck 😁', 4, 2, 12, 7, 60, 1, 1, true, true, false, false);
