INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (369, 'FBEOD for impressive gains', 'fbeod-for-impressive-gains', 'The most optimal training split, you will do these 3 workouts in rotation every other day. When you hit 8 reps on a set, add 20lbs (10lbs if its a isolation exercise) and aim for 4 reps.', 4, 2, 18, 3, 120, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (370, 'Soulsborne', 'soulsborne', 'Full body workouts with a good amount of volume, touching on some lower rep work on compound lifts however not training for 1 rep max strength. Supersets thrown in for added volume and cardio benefits, as well as engaging in cardio on at least some days off (can be as simple as walking outside/on a treadmill or whichever method you prefer). IMPORTANT note: This is to be done 1 day on, 1 day off. With 5 training days that means the weeks are 10 days long. So 1 week on the program on the app, is almost closer to two weeks time. Not crazy important, just make sure you take a rest day in between sessions. Add sets if you''d like, however give each day a try and see how you recover before making those changes. Cheers!', 4, 3, 9, 5, 70, 1, 1, true, true, false, false);
