INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (384, '5 Day Upper Lower Split - Strength and Hypertropy', '5-day-upper-lower-split---strength-and-hypertropy', 'This program is designed for lifters who want to improve their strength while fully stimulating hypertrophy. Workouts are designed around an upper lower split with an accessory day in the middle to hit abs, forearms, and neck. This accessory day is not required if you want to turn the program into a 4 day split. Workouts start with compound lifts for building strength then use isolation exercises to fully get muscles to failure. If in a time crunch, compound lifts can be skipped for hypertrophy benefits. For each exercise do 3-4 sets, whatever is more comfortable.', 7, 2, 14, 5, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (385, 'Total Fit by sól', 'total-fit-by-sl', 'This 12-week exercise program is designed to help individuals achieve a complete body transformation by building strength, enhancing flexibility, and improving balance. Tailored for those with a foundation in fitness, this program includes a balanced mix of strength training, high-intensity interval training (HIIT), and full-body flexibility and balance exercises. Each week consists of four structured workouts that progressively increase in intensity to ensure continuous improvement in physical fitness and overall health. Whether you’re looking to build muscle, lose weight, or improve your flexibility and balance, this program provides the guidance and structure needed to achieve your fitness goals.', 2, 3, 12, 4, 60, 1, 1, true, true, false, false);
