INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (399, 'New entry (Upper _Lower)', 'new-entry-upper-_lower', 'The purpose of this 12‑week Upper/Lower split workout program is to promote balanced hypertrophy and strength gains by dividing training sessions into dedicated upper‑body and lower‑body days, with a particular emphasis on maximizing lower‑limb development. By isolating muscle groups across four weekly workouts, the program allows for sufficient training volume and recovery, thereby optimizing the anabolic environment needed for muscle fiber growth. Specifically, targeted exercise selection—such as heavy compound movements (e.g., back squats, Romanian deadlifts) and complementary isolation work (e.g., leg extensions, seated calf raises)—combined with progressive overload protocols (e.g., incremental increases in load, volume, or time under tension) aims to stimulate the quads, hamstrings, glutes, and calves more effectively. In doing so, this program seeks not only to increase overall leg circumference and muscular definition but also to improve functional lower‑body strength and injury resistance, supporting both athletic performance and everyday movement quality.', 2, 1, 12, 4, 80, 1, 1, true, true, false, false);
