INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (409, '12 Week Amped Up', '12-week-amped-up', 'The JR 12-Week Bodybuilding Plan is designed to help you build muscle, burn fat, and increase strength through a structured mix of progressive weight training, targeted hypertrophy, and strategic cardio sessions. This program balances machines, free weights, and HIIT workouts to maximize muscle growth while shedding excess fat. Whether you''re starting fresh or leveling up your fitness game, this plan will keep you amped up and on track to achieve your best physique. 💪🔥', 4, 1, 12, 6, 60, 1, 1, true, true, false, false);
