INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (435, 'The Feared Athlete', 'the-feared-athlete', 'PHUL, but revised with a few tweaks and additions for athletes. This program is based loosely on PHUL.', 2, 2, 12, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (436, 'Natty Killer', 'natty-killer', 'If nothing changes, then nothing changes. This program is designed around a high volume powerbuilding program. The premise of the program being if you''re doing heavy weight, then the volume for reps will be low while the sets will be high, and if your training hypertrophy then then volume of reps will increase while sets stay low. I am not a specialist by any means. However, I like to think I understand myself and the average gym goer with similar goals enough to know how far we need to be pushed in order to make progress. This program is being designed by me to break my lifting plateaus.  I''ve been lifting for about 8 years naturally without following a program and have discovered that I am no longer making progress in my strength. I''m also not willing to eat like a fat ass to push more weights as i am already personally at the limit of what I consider healthy for my weight. With this program, I''m using what I considered to be the best hypertrophy and strength methods from the programs I''ve studied and use them to continue and build muscle while gaining strength. There are no deadlifts in this program. Since this uses 4 days out of the week, if you value the deadlift, you can easily modify this program to fit it in there. For the pin press the goal after every 4 weeks is to either A) lower the safety pins by one notch with the same weight, or B) increase the weight used with the same rep range as starting week 1. The idea is to hopefully be able to perform the overload weight with the pin continuously getting lowered to full ROM. The last few hypertrophy super sets are there for those who want to do additional arm hypertrophy workouts. I understand these workouts are longer than most (1.5-2 hour range), so if one needs to save time, they can pick and choose some of the non major compound movements depending on your goals. If you''re trying to get stronger, I would not skip any of the bench/squat sets. For a hypertrophy focus, definitely do not skip the ending sets. This is a very high volume program. With that being said if you start this program and find your body is not use to the amount of volume prescribed, then it would be best to skip a strength day (pin press bench and squat day) and stick to the first three workouts.', 4, 1, 8, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (437, 'Rodrigo''s - 6 day Arnold split', 'rodrigos---6-day-arnold-split', 'This intermediate and advanced program is designed for the bodybuilder and powerlifter who wants to increase his strength and size while pushing himself to the max. Not for the faint of heart as volume is high, but highly rewarding gains. Based on the 6 day Arnold split and adjusted to my favourite exercises.', 4, 3, 12, 6, 80, 1, 1, true, true, false, false);
