INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (457, 'The Power Shredder', 'the-power-shredder', 'The Power Shredder is a 12-week, split-style workout program designed to maximize strength, hypertrophy, and definition. It combines powerlifting techniques with high-rep hypertrophy and targeted multi-angle exercises to hit every muscle group efficiently. Each workout starts with a compound lift at low reps for strength, followed by a 10/8/6/20 rep scheme for sarcoplasmic hypertrophy, and finishes with bi- or tri-sets to ensure full muscle activation. Abdominal workouts are strategically placed throughout the week to ensure core development and aesthetics. This program is ideal for those who want to build a powerful physique with well-defined muscle groups while pushing through personal limits. Get ready to shred fat and build muscle!', 3, 2, 12, 5, 60, 1, 1, true, true, false, false);
