INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (479, 'TPP Dynamic Warmup', 'tpp-dynamic-warmup', 'This dynamic warmup is designed to prepare the body for peak performance by elevating tissue temperature, increasing blood flow, and improving joint mobility. Through a progression of controlled movements and explosive drills, it activates key muscles and primes the nervous system for strength, speed, and power training. The warmup transitions from General Dynamics, focusing on mobility and muscle activation, to Higher Dynamics, emphasizing explosive movements and nervous system priming.', 4, 3, 4, 4, 20, 1, 1, true, true, false, false);
