INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (502, 'HIT fullbody', 'hit-fullbody', 'Grow as much muscle as possible with three days a week training.', 4, 3, 12, 3, 100, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (503, 'The Nutsifyer Training Program', 'the-nutsifyer-training-program', 'The true villain of the Hard-Eyes saga. A man who used to be a reject of society turned god. After Ted Chepic rebuilt his village and it was inhabited, a man who was just slightly off moved into the town. Nobody knew the evil that percolated underneath his surface. After interactions with Ted and Alboury that made him feel pathetic, he vowed to destroy the strong and preserve only the weak and those who would obey him. That way, nobody will ever feel inadequate again at the cost of human greatness. Ironically, the one to keep people weak would be the strongest of them all.  He threw away his humanity by drinking from the pond that granted Hard-Eyes his power. He essentially became a god with unlimited telekinetic destruction abilities. His true capabilities are unknown, but he claims he could implode the entire universe. He agreed to fight Alboury without his powers, and was nearly beaten. However, he prevailed and then used his powers to heal and kill Alboury. Ted later faced him and horribly disfigured the Nutsifyer in an emotional rage. This scene alone makes the Hard-Eyes movie rated R. However, The Nutsifyer gets back up, heals himself, and starts choking Ted, who was in utter disbelief. However, from the rainforest, Hard-Eyes makes a return and paralyzes the Nutsifyer again (he had paralyzed him from a distance secretly, allowing Ted to stand a chance against the Nutsifyer). Then, Hard-Eyes tore off his head, neutralizing the threat forever. The Nutsifyer was very built, and had a specialized physique with massive arms, shoulders, and back. This is the power we will claim for ourselves.', 4, 1, 16, 5, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (504, 'The Conjugate Method', 'the-conjugate-method', 'This program was created to meet my personal needs. I encourage you to make the changes you think are necessary for you i.e. volume, accessories, etc. It is also generally encouraged to pick your max effort movements the day of, I could not leave the spots blank but hopefully what is there can provide some ideas. I also did not include any notes about accommodating resistance in the program. If you want to include accommodating resistance, I would recommend just keeping it to DE days and waving the percentage every four-week block.', 3, 2, 12, 5, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (505, 'Weight Loss Female 40+ 4 day/week', 'weight-loss-female-40-4-dayweek', 'Strength Training for weight loss for females above 40', 4, 2, 18, 4, 40, 1, 1, true, true, false, false);
