INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (507, 'Fullbody every other Day', 'fullbody-every-other-day', 'Hypertrophy and Optimal Training for me', 4, 3, 12, 3, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (508, 'Workout 🏋️', 'workout-', 'Het schema bevat zowel samengestelde oefeningen zoals squats en deadlifts als isolatieoefeningen zoals cable crunches en bicep curls, met de belangrijkste oefeningen gemarkeerd voor progressieve overload. Je begint de dagen voor benen en schouders met buik- en schouderoefeningen, en de focus ligt op het consistent verhogen van het gewicht, herhalingen of sets om spiergroei te stimuleren.', 4, 3, 8, 6, 60, 1, 1, true, true, false, false);
