INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (521, 'Robbie’s Gold', 'robbies-gold', 'Newbie gains and hypertrophy.', 2, 2, 12, 4, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (522, 'Super Saiyan Split', 'super-saiyan-split', 'This program will utilize dynamic progressive overload. Each set will done with weight where the minimum rep count can be achieved (does not have to be the same weight each set as fatigue plays a big factor) and once the maximum range can be completed, the weight will be increased. So some weeks you may only increase the weight for one set of a certain exercise, which is fine. Most exercises are using the 8-12 rep range, however compound lifts contain a first set meant to be pushed heavier at a 3-5 rep range while following the same progressive overload method. This is a 5 day a week split with 2 rest days that can be included wherever, but I personally will be running them on Tuesday and Thursday.', 2, 3, 12, 5, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (523, 'Shortcut to Size', 'shortcut-to-size', 'This program is based on the training concept called periodization. Periodization is the method of changing up your training at specified time points. The very first periodized scheme to be used with weights is called Linear Periodization (also known as Classic Periodization). That simply means that you start with light weight and high reps and as the program progresses the weights used get heavier and heavier and the reps completed per set get fewer and fewer.', 3, 2, 12, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (524, 'Foco total pra ficar no shape', 'foco-total-pra-ficar-no-shape', 'Treino intermediário masculino da AllpFit', 4, 1, 18, 3, 120, 1, 1, true, true, false, false);
