INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (568, 'The Pure Bodybuilding Program Phase 2 (Jeff Nippar', 'the-pure-bodybuilding-program-phase-2-jeff-nippar', 'Jeff Nippard’s Pure Bodybuilding Program Phase 2.0 is an advanced training program designed for individuals who have a solid foundation in bodybuilding and are looking to push their progress to the next level. This program focuses on optimizing hypertrophy (muscle growth) through a combination of science-backed techniques and structured progression. It builds on the fundamentals of strength and muscle development, but with a more specialized approach that emphasizes advanced training principles.', 3, 3, 10, 5, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (569, '3 DAYS FULLBODY WORKOUT', '3-days-fullbody-workout', 'The purpose of this program is to build strength, increase muscle mass, and improve overall fitness with efficient full-body workouts just three times a week. It balances compound and isolation exercises to ensure optimal muscle growth and recovery, making it ideal for both beginners and experienced lifters.', 8, 1, 8, 3, 70, 1, 1, true, true, false, false);
