INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (575, 'Bill Kazmaier Training Routine', 'bill-kazmaier-training-routine', 'Powerbuilding. Bill Kazmaier may have been the first true powerbuilder. He trained heavy, working the three main lifts with all assistance work twice a week. Yes, you read that correctly. The Kaz used an animalistic high intensity, high volume workout routine. He hit the deadlift, squat and bench twice a week.', 2, 2, 10, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (576, 'Easier than Easy Strength 3 Days/Week', 'easier-than-easy-strength-3-daysweek', 'Inspired by Dan John''s deep understanding of strength training, our program aims to build robust, functional strength in a sustainable manner. It focuses on consistent, high-quality practice of foundational movements, prioritizing perfect execution and ample recovery. This approach emphasizes neurological adaptation, allowing you to get stronger without constant exhaustion. The goal is to make each session contribute positively to your overall well-being, fostering long-term progress and durability. It''s about building a capable physique for life''s demands, ensuring you feel refreshed and ready for your next workout, day after day, through deliberate, incremental improvements. For more info, consider purchasing the Easy Strength Omnibook.', 4, 1, 14, 3, 40, 1, 1, true, true, false, false);
