INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (587, 'I''m a cop you idiot!', 'im-a-cop-you-idiot', 'Get fit to pass RCMP', 4, 2, 12, 5, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (588, 'Get Ready for MMA', 'get-ready-for-mma', '**Get Ready for MMA** is an 8-week program designed to elevate your fitness and prepare you for the demands of mixed martial arts. With 40 training sessions, you''ll engage in a mix of strength training and conditioning, focusing on key muscle groups essential for performance. Each workout lasts approximately 80 minutes and incorporates a variety of exercises, from incline bench presses to dead hangs, ensuring a balanced approach to building strength and endurance. Perfect for intermediate lifters looking to enhance their athleticism and physique, this program will challenge you every step of the way!', 4, 2, 8, 5, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (589, 'Simple&Clean All Kingdom, No Hearts 1.1', 'simpleclean-all-kingdom-no-hearts-11', 'These are compound lifts that interest me combined w basic cable workouts that can be subbed w barbell versions. These are focused on building a foundation while having fun. Lacking body parts being hit are chest and legs. Stress and tweaking for later. Work for 3 months then see where you body is at and then tweak the workouts to target weaknesses.', 4, 2, 12, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (590, 'Mohit’s Torso and Limbs Split', 'mohits-torso-and-limbs-split', 'Simple 4 day a week program with Torso and Limbs split. Aiming for healthy volume for each muscle group.m', 2, 1, 12, 4, 60, 1, 1, true, true, false, false);
