INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (595, 'Escanor The Lion Sin', 'escanor-the-lion-sin', 'A 4 day full body routine aiming for building strength and muscle . IMPORTANT NOTE : Every second week decrease the weight on main lifts for 2-3 extra reps', 8, 1, 12, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (596, 'Simple PPLUL', 'simple-pplul', 'The purpose is to give lifters a staple program that requires effort but what you give you get. Lifters will not have to worry about over complicating their training with unusual movements. They will also not have to worry about feeling unsatisfied after a workout because of too little volume or too much isolation.', 4, 3, 12, 5, 140, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (597, 'Pure hypertrophy 5 day program', 'pure-hypertrophy-5-day-program', 'This intermediate to advanced program focuses heavily on delts and has a 3x week frequency for the upper body and a frequency of 2x week for the lower body. The arms and delts are pretty much hit 5 times a week.o', 4, 2, 12, 5, 70, 1, 1, true, true, false, false);
