INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (599, 'Hardcore Advanced program', 'hardcore-advanced-program', 'Muscle growth, focusing on each muscle group per day, 5 days a week.', 4, 2, 12, 5, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (600, 'H12: Hypertrophy & Strength', 'h12-hypertrophy-strength', 'H12 is a 12-week, 4-day training program combining hypertrophy and strength principles to help you build serious muscle and power — whether you’re a beginner, intermediate, or advanced lifter. With progressive overload, balanced training splits, and a focus on key compound movements, the program ensures steady gains in both size and performance. Each week is designed to push you slightly further, with smart progression and recovery built in. Perfect for anyone ready to commit, lift hard, and grow stronger — regardless of experience level.', 4, 3, 12, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (601, 'The Crusade', 'the-crusade', 'This program aimed at mainly intermediates and some novices that can still work for advanced lifters,is designed to get you generally strong,pack on muscle,and teach you ways to progress your training throughout the rest of your lifting career using clusters,back off sets,and things like dynamic double progression with tried and true movements done with a 5 day a week,upper,lower,full split,this program can be run indefinitely and use one week deloads as you see fit depending on recovery and how advanced you are,you can use any variation of the compounds I list you like if you want or re run it but that’s your choice', 2, 2, 10, 5, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (602, 'The Regimen p/p/l', 'the-regimen-ppl', 'To increase musculature', 4, 1, 10, 5, 60, 1, 1, true, true, false, false);
