INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (605, 'Powerlifting Program 2.0', 'powerlifting-program-20', 'Focusing on the 3 main lifts (Squat, Bench & Deadlift) while also isolating certain muscles that play a role in powerlifting training. The program will follow an upper/lower split that consists of 3 Bench, 2 Squat & 2 Deadlift days per week (@ a 6 day per week split & 12 week long program)', 4, 2, 12, 6, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (606, 'Tank Maxxing (Upper Lower)', 'tank-maxxing-upper-lower', 'A beginner bodybuilding program designed to help you out with the basics. With only four days a week to minimize time in the gym, but still push for quality working sets. Not meant to be run by complete novices but can be if wanted to (Novice program coming soon) but meant for those who have a taste of the gym. Yet still have much to learn and accomplish, who want to get there without program hopping.', 4, 3, 12, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (607, 'PPLUL / Push, Pull, Legs, Upper Lower (Alternate)', 'pplul-push-pull-legs-upper-lower-alternate', 'Utilize the PPLUL plan in order to work all muscle groups twice per week with adequate rest between workouts. Recommend day 1 starting on Monday and for rest days to be Thursdays and Sundays.', 4, 3, 10, 5, 60, 1, 1, true, true, false, false);
