INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (612, '5 day split', '5-day-split', 'Basic 5 day split, play with the volume as you like to maximize recovery or effort in your workouts. Mostly every muscle group is covered in the program. I made this solely for my training to have a complete routine so feel free to add/switch/remove exercises to your leisure!', 8, 3, 10, 5, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (613, 'GRØJ-GAINZ', 'grj-gainz', 'Do you have a home gym with limited equipment? Do you want door frames to be terrified of your arrival? Do you want to incorporate Powerlifting, Bodybuilding, and calisthenics into your routine? This program is for you if you answered yes to all of those.', 2, 2, 12, 4, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (614, 'Push, Pull, Legs, Chest and Back, Arms, and Legs', 'push-pull-legs-chest-and-back-arms-and-legs', 'Advanced muscle training program that’s 3 days on 1 day off.', 4, 3, 10, 6, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (615, 'PHUL 12 Week Program!', 'phul-12-week-program', 'The Purpose of this program is to build size and strength at the same time. This 4 day split includes an upper body strength day and a lower body strength day. These will mainly include the compound movements with a couple of isolation movements as well. It then also includes a upper and a lower hypertrophy day. This will mean higher reps with less weight.', 2, 2, 12, 4, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (616, 'Weightlifting Mobility program', 'weightlifting-mobility-program', 'This program is designed to help athletes succeed in building their mobility and core in all areas.', 8, 3, 7, 5, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (617, 'Bigger leaner stronger plus cardio', 'bigger-leaner-stronger-plus-cardio', 'This plan is designed to build muscle, get lean, and improve cardiovascular capacity and realistic!!. It should be completed within 1hour. Keep the exercises strict form, with a controlled tempo of 2 seconds down and 2 seconds up no additional exercises needed we don’t want to burn out. Outside of the gym, ensure you get the correct amount of sleep and aim for 10,000 steps a day. If you drink keep it minimal and once a week lay off the cigarettes eat clean and portion control. every couple of days treat your self to a 1 snack of your choice.', 2, 2, 10, 4, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (618, 'Silver Specialization', 'silver-specialization', 'A high volume program, full body, 4 days a week, with an emphasis on arms, shoulders, and back.', 4, 3, 12, 8, 100, 1, 1, true, true, false, false);
