INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (620, 'Warrior', 'warrior', 'Warrior is for the people that want to be strong, functional, and big all at the same time.', 4, 3, 12, 4, 90, 1, 1, true, true, false, false);
