INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (624, 'High Volume 5 days 8 weeks', 'high-volume-5-days-8-weeks', 'High Volume Training for experienced lifters who wants to try a very effective way to build muscle or break the Plato', 2, 2, 8, 6, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (625, 'Adrian’s powerbuilding 2024', 'adrians-powerbuilding-2024', 'Optimize your strength and look. Get a smart program for 5 days per week 🙌🏻', 4, 2, 12, 5, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (626, 'From Flap Jacks to Thick Stacks', 'from-flap-jacks-to-thick-stacks', 'Flap Jacks 2 Thick Stacks is a specialized fitness program designed to help individuals build bigger, stronger glutes and well-developed leg muscles. Through a structured combination of resistance training, progressive overload, and targeted lower-body exercises, this program focuses on enhancing lower-body strength, size, and shape. Whether you''re looking to grow those glutes, stack on muscle, or simply level up your leg-day game, this program serves up results—thick and strong, just like the name suggests.', 8, 2, 10, 5, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (627, '5 day Upper Lower Split', '5-day-upper-lower-split', 'Hypertrophy Upper Lower Split', 4, 2, 8, 5, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (628, 'Workout program to get BIG', 'workout-program-to-get-big', 'Build muscle and strength, to get from the beginner to intermediate stage of lifting. The goal is to hit a 225 bench, 315 squat, and 405 deadlift for atleast one rep each by the end of the program. If the desired strength goals have not been reached by the end of the program, repeat it as long as needed.', 2, 3, 12, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (629, 'locked in (1)', 'locked-in-1', 'to build muscle and power', 4, 3, 10, 6, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (630, 'Upper Body Builder with Leg Boost', 'upper-body-builder-with-leg-boost', 'The “Upper Body Builder with Leg Boost” is a 12-week fitness routine designed to maximize upper body hypertrophy while incorporating essential leg exercises for balanced development. Perfect for beginners with 6-8 months of fitness experience, this 3-day-per-week program seamlessly integrates upper body and leg workouts within each session, ensuring comprehensive muscle growth without an extensive focus on leg training. The program is structured in three phases—building foundation, progressive overload, and peak phase—each lasting four weeks to progressively challenge and enhance your strength and muscle definition. With up to 90 minutes per session, this routine is ideal for those committed to sculpting a stronger, well-defined upper body while maintaining overall fitness.', 4, 2, 12, 3, 10, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (631, 'Swoletariat 2.0', 'swoletariat-20', 'This is an intermediate program for high responders. The first half will do heavy enough weights to maintain the skill and enjoyment of strength training while prioritizing hypertrophy and volume with your accessory movements. The second half will is strength and peaking.', 4, 2, 16, 4, 120, 1, 1, true, true, false, false);
