INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (647, 'Dev lifts - upper/lower Fb', 'dev-lifts---upperlower-fb', '**Dev Lifts - Upper/Lower FB** is an 8-week program designed specifically for men, focusing on building strength and muscle through a balanced upper and lower body split. With workouts scheduled for six days a week, you''ll engage in a variety of exercises targeting all major muscle groups, including preacher curls, squats, and bench presses, all while keeping intensity high with a 4-9 rep range. Each session is crafted to push your limits and maximize gains, ensuring you stay motivated and on track to achieve your fitness goals. Get ready to transform your physique and elevate your lifting game!', 4, 3, 8, 7, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (648, 'Pure hypertrophy', 'pure-hypertrophy', 'Pure hypertrophy program', 2, 3, 10, 5, 120, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (649, 'Powerlifting Program (1)', 'powerlifting-program-1', 'Total SBD, Strength & hypertrophy', 2, 3, 12, 5, 100, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (650, 'Ted Chepic Program', 'ted-chepic-program', 'An intermediate/advanced program designed by yours truly, which I envision creating the physique of the fictional hero, Ted Chepic. Ted comes from the “Hard-Eyes” album, my first musical creation unleashed to the world. Ted fearlessly fought Hard-Eyes, a supernatural frog the size of a truck with unstoppable killing abilities, and came out on top. He didn’t care whether he lived or died, he had just witnessed the incredible strength of an unstoppable creature destroy his entire village and his lover. Hardeyes killed everyone he ever cared about. When he returned to his village and saw the blanket of his friend’s baby on the ground with his village destroyed, he knew something horrible had happened. He dropped to his knees, only to get back up and frantically search for the other people he cared about. There were no survivors. He later found his girlfriend, and she was no longer alive. Consumed by rage, he drew his sword and followed the beast on top of a volcano. He was met with unstoppable strength, and it nearly killed him. However, from sheer perseverance, bloodlust, vengeance, and strength, he managed to severely wound Hard-Eyes, and the beast fell from the volcano, and his body was not found. This is the heroism, or rather lack of it, that we are looking to encompass.', 2, 2, 12, 5, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (651, 'Excelsior program!', 'excelsior-program', 'This program is a 8 day split that includes an upper, lower, and arms day. So 3 days on and 1 off. A split made by a good friend of mine with excercise selection for those who are fans of GVS,NH,BOM,and Alex Leonidas. Please support me Dumbcalidude dude on Instagram and Youtube. Thanks to the great Croissantrophy as well!', 4, 2, 12, 6, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (652, 'Get fit for vacation', 'get-fit-for-vacation', 'Build strength and work on hypertrophy. Run while in a slight calorie deficit', 4, 1, 12, 4, 60, 1, 1, true, true, false, false);
