INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (673, 'Powerbuilding PPL by Bad News Barnes', 'powerbuilding-ppl-by-bad-news-barnes', 'This program is designed to build strength and muscle in a fairly balanced process. 5 lb weekly increases for main lifts and 10 lb bi-weekly increases for supporting exercises. Week 5 is a deload week so  ideally at the end of the program you should add 40 lb to your main lifts. This is a program  for intermediate - advanced lifters who may find themselves needing to break through a plateau or break-up there current program. I wouldn''t recommend this for beginners or novice lifters. New lifters would benefit more from a program with less workout frequency lower volume and larger weight increases. You could repeat this program back to back but it may become stressful pushing all sets to failure / near-failure.', 4, 2, 9, 6, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (674, 'Phat Ape', 'phat-ape', 'Linear Wave Progression Body building program based on Eric Helm’s Intermediate sample program.', 3, 3, 12, 4, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (675, 'Harry''s Power Building Program Version H2A', 'harrys-power-building-program-version-h2a', 'Abstract: This program was developed and methodically produced based on Harrison S. McDermott’s personal knowledge and understanding of hypertrophy and strength gain. This program is NOT intended to be a typical program, or to be used as the pinnacle of power building training. This program is intended for the use of individuals who are beyond beginners, and well into the intermediate and potentially advanced end of the training spectrum.', 2, 2, 8, 6, 60, 1, 1, true, true, false, false);
