INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (681, 'Women’s 4 Day Upper Strength/Lower Hypertrophy', 'womens-4-day-upper-strengthlower-hypertrophy', 'Introducing my Women’s 4-Day Glute-Focused Upper/Lower Hypertrophy Program—designed for those looking to build strong, sculpted muscles while enhancing an hourglass figure. This program strategically combines intense lower-body glute workouts with balanced upper-body training, emphasizing muscle growth and symmetry. Perfect for women aiming to enhance their curves, especially in the glutes, while maintaining overall strength and balance. For best results, this program is ideal when paired with a caloric surplus, ensuring your body has the fuel needed to grow and shape those muscles. Whether you’re looking to boost your strength or create a more defined silhouette, this program is your path to achieving some serious gains.', 8, 2, 8, 4, 90, 1, 1, true, true, false, false);
