INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (691, '15 min workout', '15-min-workout', 'To fit in a focused workout in a short time. 4-5 days a week. Supersets, rest pause, and drop set techniques, to maximize time. Fresh mind, every set counts. Because time is a limiting factor, use lightweight.  Going too heavy can lead to injuries. This is very focused, and hard, yet you should leave the gym feeling great!', 2, 2, 12, 5, 20, 1, 1, true, true, false, false);
