INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (695, 'Upper Lower (3:1 split, abs focus)', 'upper-lower-31-split-abs-focus', 'Personal use. Variation of upper lower 4 day split with focus on abs during lower days.', 4, 3, 12, 4, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (696, 'Ultimate Beast Booty Workout Program - 4 Day Split', 'ultimate-beast-booty-workout-program---4-day-split', 'This program is designed for women looking to maximise their glute growth while still building proportional strength throughout their body. The program is split into a 4 day legs, push, pull, legs split, with the first leg day having an emphasis on glutes. This program is ideal for intermediate to advanced lifters looking to build off their first year of lifting.', 4, 1, 12, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (697, '2 upper 2 lower + arms', '2-upper-2-lower-arms', 'Powerlifting hypertrophy', 4, 2, 12, 4, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (698, 'IRONCLAD ULPPLH', 'ironclad-ulpplh', 'Ironclad is a highly efficient, results-driven powerbuilding program designed to maximize strength, hypertrophy, and conditioning in 40-minute sessions while ensuring optimal recovery and sustainability. Built around classic compound lifts, targeted hypertrophy-focused accessories, and progressive overload, it strikes the perfect balance between raw strength development and aesthetic muscle growth.', 2, 2, 10, 6, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (699, 'The Essentials Program 5x', 'the-essentials-program-5x', 'Jeff Nippard''s Essentials Program - 5x/Week', 2, 1, 12, 5, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (700, 'Bodybuilding for jiu jitsu', 'bodybuilding-for-jiu-jitsu', 'This program is designed to improve my body, improve my jiu-jitsu, and provide time for recovery in my schedule.', 3, 1, 12, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (701, 'Ertenan’s body building program', 'ertenans-body-building-program', 'Helps build most of your body', 2, 2, 8, 5, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (702, 'Rey’s high frequency training U/L/Limbs', 'reys-high-frequency-training-ullimbs', 'This is a program leaning towards more advanced trainees but also if you’re new and ready to push the volume then fuck it try it out. I’m no expert just a guy trying to introduce a high volume slay fest and see how I respond. Obviously these are more like guidelines than a strict program', 4, 2, 6, 6, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (703, 'ATHLETE PROGRAM', 'athlete-program', 'This program is built to increase strength whilst also building speed and power. This is done by performing strength based exercises supersetted with plyometrics such as box jumps.', 3, 2, 8, 5, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (704, 'Rabid Dog', 'rabid-dog', 'A minimalist approach to both strength and size with added bonus of moderate cardio as a strategy for keeping fat in check while on a caloric surplus', 8, 2, 8, 5, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (705, 'The Allabeast - Hybrid Lift/Run', 'the-allabeast---hybrid-liftrun', 'Program designed for quick and effective workouts focusing on a bit of strength and hypertrophy. Created by a father with a newborn who has limited time. Designed to be ran along with 2-3 days of  mild running and optional jump rope for a bit of added cardio.', 4, 2, 12, 6, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (706, 'Ahmad’s 10 week Powerbuilding Program.', 'ahmads-10-week-powerbuilding-program', 'The program is centred around maximising a progressive increase in strength on the Powerlifts, as well as focusing on hypetrophy in a way that targets muscle groups proportionally, to build the best of both worlds. At the end of this program, you will also be testing out your 1RMs on each of the Powerlifts to see how far you’ve come.', 4, 1, 10, 5, 120, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (707, 'Poland Powerbulding', 'poland-powerbulding', 'a powerful powerbuilding plan after which you will observe incredible gains and strength. Polish powerbuilding plan written for 8 weeks with deload, the peaking phase finished with repair. After 16 weeks we can repeat the plan, and if you want you can modify the exercises or series. In the main lifts such as bench press, military press, deadlift, front squat, squat we add from 2.5 kg to 5 kg in each training, in pull-ups we add weight in each series so that it comes out at least 5 series', 3, 3, 16, 5, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (708, 'I am Old School', 'i-am-old-school', 'Old school inspired program that utilizes concepts from the golden era of bodybuilding.', 4, 1, 12, 3, 60, 1, 1, true, true, false, false);
