INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (717, 'PPL+1: Precision Progression', 'ppl1-precision-progression', 'PPL+1: Precision Progression is a 4-day training split built on the proven Push-Pull-Legs framework, with a dedicated fourth day tailored to your unique weak points. Whether it''s lagging muscle groups, mobility deficits, or accessory lifts that need attention, the +1 day gives you the flexibility to target what matters most. This program is designed for intermediate to advanced lifters who want balanced development, reduced plateaus, and improved symmetry. Stay structured, stay focused—train with precision.', 4, 2, 13, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (718, 'Offensive lineman', 'offensive-lineman', 'To get better at offensive line', 4, 3, 10, 5, 100, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (719, '12 Week Crusader Mode', '12-week-crusader-mode', 'Three week meso cycles for nine weeks increasing reps from week to week. Then accessory work drops off while volume and weight go up further for compounds. Last week is a small deload with SBD day for skill maintenance before comp day or gym PRs with squat and deadlift being separate days.', 2, 2, 12, 5, 70, 1, 1, true, true, false, false);
