INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (722, 'Science Based Ideal Upper Lower 4 Day Split', 'science-based-ideal-upper-lower-4-day-split', 'The 4 day upper lower split has been designed based on Jeff Nippard’s tier lists for isolating each muscle. The program is meant for novice to intermediate lifters looking to improve their physique in the best way according to science, emphasizing a deep stretch on the muscles. Each week switches the initial compound lift to be either barbell or dumbbell focused.', 4, 2, 16, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (723, 'Hasumo', 'hasumo', 'Improve the weakest points, training more muscle linked with SBD. Wish you have a nice day. Plz comment for me to know how your feeling and i will change to make it better and better .', 2, 1, 8, 4, 120, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (724, 'Grappler Baki', 'grappler-baki', 'Like most programs I use or create, this program is a little bit of everything. I want you to get lean, jacked, and athletic. In the spirit of Baki, we’ll have some athletic movements with heavy bag/shadow boxing, calisthenics, and barbell movements to round out your physique. This program will take virtually everything to failure, barring a few exercises. You will get stronger during this program, but it’s taking a back burner to building your physique, improving calisthenics, your work capacity, and your athleticism.', 4, 1, 12, 5, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (725, 'Leo''s amazing split', 'leos-amazing-split', 'Build muscle and enjoy lifting at the gym', 4, 2, 12, 4, 60, 1, 1, true, true, false, false);
