INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (727, 'Trial of the Grasses - Witcher Workout', 'trial-of-the-grasses---witcher-workout', 'Inspired by the legendary White Wolf, the Witcher Routine is a four-day hybrid program combining strength, functional fitness, and core work designed to sculpt a lean, powerful, and agile body. It incorporates structured strength training, explosive cardio, and focused core development to embody Geralt’s combination of strength, endurance, and combat-readiness. Perfect for those looking to adopt a disciplined, Witcher-like lifestyle.', 2, 1, 8, 5, 60, 1, 1, true, true, false, false);
