INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (750, 'Aidan’s Program 2.0', 'aidans-program-20', 'Get big. Deload sometime between week 4 and 8 depending on when fatigue sets in. If you are cutting it will be closer to 4 and closer to 8 when bulking. Increase load weekly and reps if possible (unless you weren’t in the rep range during previous week). Start at RPE 7 and move to RPE 9 during progression. For deload do day 1-3 cutting sets and reps by half, day 4-6 cut sets, reps, and weight in half.', 2, 2, 8, 6, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (751, 'Alex Leonidas Novice Program (AlphaDestiny)', 'alex-leonidas-novice-program-alphadestiny', 'This is a novice program designed for first year lifters. If you cannot bench 225×5, squat 315×5, and deadlift 405×5, then you are probably a novice lifter. A simple way to assess your training level is if you can still make linear progress workout to workout. If the answer is yes, then you’re a novice lifter. This means you must build your foundation with a simple program like this. So check your ego at the door, and prepare to make the best gains of your entire life.', 4, 3, 12, 3, 90, 1, 1, true, true, false, false);
