INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (762, 'Modified Mike Tyson Inspired At-Home Training', 'modified-mike-tyson-inspired-at-home-training', 'The purpose for modifying the Mike Tyson Inspired At-Home Training Program is to create a Novice workout that exists in between the Beginner and Intermediate levels. The main purpose is to retain the commitment and skill level of the Intermediate, but choosing exercises that favor taller individuals with less flexibility and who struggle with exercises that require motions that bring surges of blood rushing to the head (i .e. Crunches, Bear walk, etc.) and take advantage of a pull-up/dip tower, dumbbells, and body weight bands.', 3, 2, 8, 4, 30, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (763, 'S6 Program (1)', 's6-program-1', 'My program is one that balances fitness and overall health, taking into account your body’s needs and capabilities. By following a regular and comprehensive exercise plan, you can achieve your goals, whether they are building muscle, improving endurance, or even losing weight. An effective exercise regimen is not just about exercise, but also includes proper nutrition and adequate rest, which helps your body recover and grow. Most importantly, enjoy your workout, as consistency is the key to achieving sustainable results.', 4, 3, 7, 5, 60, 1, 1, true, true, false, false);
