INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (788, 'Tim’s Powerbuilding Program', 'tims-powerbuilding-program', 'This program combines key aspects of powerlifting, and bodybuilding to increase your one rep max for squat, bench, and deadlift. At the same time it will also target muscles that help you build a more “aesthetic” look. This program can also easily adapt to your schedule. Whether you can work out 3, 4, or 5 days a week, simply go to the gym when you can and do the next day in rotation. Just don’t skip or rest more than 3 days in a row. Due to the intensity of the program, don’t work out more than 3 days in a row. Try this program and watch your overall strength increase!', 8, 3, 10, 4, 100, 1, 1, true, true, false, false);
