INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (795, 'U/L/A/U/L', 'ulaul', 'Intermediate program 5x days a week. This is a modified version of natural hypertrophy’s intermediate program, I just made a couple tweaks to an already good program. It’s a bodybuilding focused program but feel free to go heavy on initial compounds if you like, 4-6 rep sets. 0-2 reps within failure for compounds and take isolations to or beyond failure. Use double progression but if you begin to stall after a couple of weeks reduce to 1 set for everything for one week to deload a bit and reset fatigue.', 3, 3, 12, 5, 90, 1, 1, true, true, false, false);
