INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (800, 'Robert Gets Ripped', 'robert-gets-ripped', 'Introductory program to build a base strength. This program will increase size and strength and should be a good baseline to jump up to something more advanced afterwards.', 4, 1, 12, 3, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (801, 'Natural Hypertrohpy - Guts Workout Program', 'natural-hypertrohpy---guts-workout-program', 'An altered vertsion of NH''s new Guts routine that caters more to my needs. I added more forarm work, less DB back work since it''s easier for me to load barbell. Moved the RDL to Lower 2 instead of DL. Rest you can see what I added.', 2, 3, 12, 4, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (802, 'Top3fitness Power Lifting', 'top3fitness-power-lifting', 'Here is a 12-week powerlifting program designed to increase your squat, bench press, and deadlift. This program is structured with periodization in mind, meaning that the intensity will gradually increase over the 12 weeks. The main focus is on increasing strength while allowing for recovery and adaptation.', 8, 3, 12, 4, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (803, 'Brute Force', 'brute-force', 'Breaks plateaus through brute force on the main lifts (Squat, Bench, Deadlift, Overhead Press). To start pick the heavy weight your stuck at and do that for the first 3 sets, then drop the weight for the higher rep range sets. When you can hit 6 reps for the heavy sets add 10 pounds for the Squat and Dead and 5 for the presses. Feel free to switch up the accessory movements but preform them the same way and you might want to switch them on weeks 7-12. I also mean tricep dips. The Rpe’s are a little wonky because this is a lot of bro science. It did in crease my bench by 40lbs so that’s cool. Have a rest day between days 2 and 3 and have 2 rest days between days 4 and 1.', 4, 3, 12, 8, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (804, 'Glutes, shoulder and back.', 'glutes-shoulder-and-back', 'Perfect for a transition from a normal split to a more advanced one', 4, 3, 8, 5, 80, 1, 1, true, true, false, false);
