INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (847, 'Targeted Muscle Groups Alternating', 'targeted-muscle-groups-alternating', 'With only a cable machine, smith machine, and dumbbells in the apartment gym, we''ve got to make some modifications.', 4, 2, 10, 4, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (848, 'Beast''s powerlifting programm', 'beasts-powerlifting-programm', 'This programm focusses on building a strong RAW squat, benchpress and deadlift. It is made for people who like heavy lifting and want a programm that doesn''t take month to complete. It is not meant for new lifters and has a fair bit of my personal preferences in it. It consists of 3 Main days where the Lift is performaded, followed by an exercise to address weaknesses, followed by an exercise for Hypertrophy and ends with some accessory work. One day per week is dynamic effort day which is for power (here some heavy upper body is mixed in to have a second day with heavy pressing in it). Two days per week should be cardio to focus on all over fitness and improve cardiovaskular performance. One day should be a complete rest day. Tge first two weeks focus on 4-5 reps as top sets, the next two weeks on 3-4 reps. The fifth week is supposed to be either for a new 1RM or a new 2RM. Anyway, this is how I train. If you want to try it, on your own risk. For me it works well.', 2, 2, 5, 6, 80, 1, 1, true, true, false, false);
