INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (851, 'Progressive overload', 'progressive-overload', 'This program is designed to help beginner to intermediate weight lifters build muscle and strength using evidence based training principles.', 8, 3, 12, 4, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (852, 'FKPL COMP PREP V2', 'fkpl-comp-prep-v2', 'To limit errors from the last comp', 8, 1, 16, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (853, 'Colly C’s Mass Routine', 'colly-cs-mass-routine', 'You’re going to hit a workout every other day. You lift, skip a day, and then lift again. You will run through about 4 workouts in one week then you repeat. I’d recommend doing a running session at least once a week and you are welcome to throw in some cardio every workout. Oh by the way, you’re going to want to take 2:30-4:00 min rest periods in between each set to make sure Lucifer stores are filled and so you don’t exhaust yourself. You want every ounce of energy for each set. This isn’t body part focused but after 8 weeks you can start targeting specific muscles like arms or quads or shoulders. For now, this is frequent enough and with enough rest days to ensure you’re eating enough carbs and protein in between meals. Extra days gives you extra time to increase your glycogen levels. This program is meant for general size growth. Back to the basics.', 8, 2, 8, 4, 90, 1, 1, true, true, false, false);
