INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (866, 'DBP 2.0', 'dbp-20', 'Gain strength and muscle mass. From week to week, you can change all the exercises and move them around just don''t touch bench or deadlift. If your joints cannot handle bench/deadlift/squat or you don''t have access to a free barbell, then you can replace them with a similar exercise. BTW remember that this is my program, and some people respond to this amount of volume paired with intensity differently than I. (All sets should be taken to RPE 8.5+). I have two back days because I view my back as a weak point I want to make a strong point. People with weak delts or chest might want to have multiple chest or delt days. Anyways enjoy the program.', 4, 1, 5, 7, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (867, 'PPL BEGINNER', 'ppl-beginner', 'PPL PROGRAM FOR BEGINNERS FOR BODYBUILDING PURPOSES', 4, 2, 8, 3, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (868, 'Newbie weights', 'newbie-weights', 'Embark on your strength journey with the Newbie Weights program, designed specifically for beginners looking to build muscle and sculpt their physique over 10 weeks. This comprehensive plan features 10 workouts per week, each lasting around 60 minutes, focusing on essential compound and isolation movements. You''ll engage major muscle groups through effective exercises like the Leg Press, Chest Fly, and Seated Row, ensuring a balanced approach to strength training. Get ready to transform your body and develop a solid foundation for future gains!', 8, 3, 10, 1, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (869, 'BeanBuilding', 'beanbuilding', 'This program leads up to a strength peak in week 10. Before this, you progress each week with weight or reps. It is a sort of “Bro-Split” for hypotrophy, but also prepares you for a 1RM on each of the Big 3: Squat, Bench, Deadlift. Ultimately, the goal of this program is to grow and develop superior strength for a 1RM.', 2, 2, 11, 4, 70, 1, 1, true, true, false, false);
