INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (913, 'Four Day - MEV Split', 'four-day---mev-split', 'This is designed to help all gym goers reduce time and junk volume and get good results by training efficiently.', 2, 2, 10, 4, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (914, 'Superman Remastered', 'superman-remastered', 'Muscle growth and fat loss.  During rest periods of one minute, do cardioacceleration (sprinting in place, mountain climbers, step-ups, squat jumps, etc) or do 4 minute Tabata at end of workout for first 2 weeks, then two sets of 4 minute Tabata at end of workouts for weeks 3-5.  Realize Tabata at end will ad to expected time to complete workouts.', 2, 3, 5, 6, 50, 1, 1, true, true, false, false);
