INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (917, 'HLM 3x Full Body', 'hlm-3x-full-body', '3-day full-body workout program designed to hit every major muscle group twice per week while staying within 85-90 minutes per session, ensuring adequate volume (10-20 weekly sets) and recovery. Each workout focuses on compound lifts with accessory work to round out muscle development.', 2, 2, 8, 3, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (918, 'Buff Babe Summer', 'buff-babe-summer', 'Keep muscles as juicy as possible on cut. Cardio is included in a few days on this program, but aim to do at a minimum 3 cardio sessions per week. These should be 30-45 minutes at a moderate intensity. Calories should be limited based on BMR and protein intake is crucial to success in this program, 0.8g-1g/lb of bodyweight.', 8, 1, 8, 4, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (919, 'Low Volume Push Pull Legs', 'low-volume-push-pull-legs', 'For muscle growth. You can run 6 days 1 off or 3 days 1 off repeat. up to you. For warmups do 2-3. Ex on lateral raise working weight 30lbs. 15lbs for 5-8 reps, then 22.5lbs for 1-3 reps. Rest between 2-3 minutes between warmups and for working set 3-4. On leg press for example that warm up method might not apply. My working set 7 plates. I just add a plate each side, do a few reps, rest 2 mins repeat until my final warm up, I do 1 rep. Let me know if you got questions. My tiktok @luis_shz69.', 2, 2, 12, 3, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (920, 'Abercrombie Model - Phase I', 'abercrombie-model---phase-i', 'The first phase of the Abercrombie Model Workout is the “Muscle Prep” phase. The “Muscle Prep” phase is a short one-month workout program designed to build a solid muscle and strength base. If you already have a solid base from being on a current workout routine, this phase can be skipped and you can move on to the Mass Building Phase (Phase II). However, if you haven’t been working out consistently for at least a month, it’s best to complete this stage of the workout before moving on.', 4, 3, 4, 7, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (921, 'HSP Periodization', 'hsp-periodization', 'Periodization program for select exercises covering Hypertrophy (4 weeks), Strength (4 weeks), and Power (4 weeks).', 2, 2, 12, 3, 60, 1, 1, true, true, false, false);
