INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (953, 'Turbo Diesel 4 Day Linear Progression', 'turbo-diesel-4-day-linear-progression', '4 Day per week LP meant to be run two days on, one day off, two days on two days off ex: Mon, Tues, Thurs, Fri. This is a 4 day split linear progression intended for novices new to lifting and late-novice/intermediate lifters coming off of a long layoff and looking for a bridge program. Each day will have two primary compound lifts. 5-10 lbs added each session for the squat, deadlift and clean with 2.5-5lbs added for the pressing movements. On deadlift we will use a + set to squeeze more out of our good workouts and prevent stalls. The primary lifts will be the low bar squat, deadlift (conventional please), bench press, overhead press, and the power clean. Some basic accessories are programmed as well. Add additional accessories as needed or desired. Dips, pull overs, lateral raises, skull crushers, and rowing variations all in the 8-12 rep range all recommended accessory work to be dosed as desired but not required. Pull-up/chins should use assistance or weight as needed to to hit 5-8 rep range. Program is written for 6 weeks but can be rode out until progression stops. Workouts are either A,B or C. I would try to run out the ACAB sequence out to 12 or even 16 weeks for a newer lifter (SKINNY GUYS NEED TO EAT)', 4, 3, 6, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (954, 'Andreas general strength and fitness program', 'andreas-general-strength-and-fitness-program', 'This program is made to develop basic strength and good technique for compound exercises.', 4, 2, 10, 3, 60, 1, 1, true, true, false, false);
