INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (963, 'Thunder Thighs', 'thunder-thighs', 'Strong legs are the foundation of power and performance. This program is built around heavy squats, posterior chain work, and unilateral movements to maximize strength, size, and explosiveness. Romanian deadlifts, hip thrusts, and lunges develop stability and balance, while paused squats and sled drags improve speed and endurance. Mobility and recovery are just as important to keep you moving pain-free. Whether you’re chasing PRs or just want stronger legs, this plan will get you there. Train hard and stay consistent.', 2, 2, 4, 5, 70, 1, 1, true, true, false, false);
