INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (980, 'Alpha Destiny Novice Program', 'alpha-destiny-novice-program', 'This is a novice program designed for first year lifters. If you cannot bench 225x5, squat 315x5, and deadlift 405x5, then you are probably a novice lifter. A simple way to assess your training level is if you can still make linear progress workout to workout. If the answer is yes, then you’re a novice lifter: This means you must build your foundation with simple program like this. So check your ego at the door, and prepare to make the best gains of your entire life. The good news is that it will only take you 6-15 months at the absolute max.', 3, 2, 8, 3, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (981, 'GOLDEN ERA HIT WORKOUT', 'golden-era-hit-workout', 'Build Muscle And Gain Strength with only 3 short workouts per week', 8, 1, 12, 3, 30, 1, 1, true, true, false, false);
