INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (983, 'PrimalMass', 'primalmass', 'Gets you huge in the right places. Very strong focus on back and triceps, about 12 sets per week for those. About 7-8 sets for chest, so a strong point there is required. Same for biceps, from 5 to 7 sets. Legs get destroyed. Will catch up upper back thickness lag in the first part of the program. Then with newbuilt said thick back regular exercises can be performed easier. I recommend Training forearms and neck at home.', 4, 1, 12, 3, 60, 1, 1, true, true, false, false);
