INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1005, '5/3/1 (1)', '531-1', 'A linear consistent program for intermediate lifters using a alternate version of 5/3/1 beyond use TM or 90% of your 1RM (every third set is a AMRAP set and on the 4-6 weeks and if you run the program again add 5-10 pounds on your TM total for bench and 10-15 pounds on your deadlift and squat TM). Also every joker set (100% sets) is optional if you are feeling strong but is required on the 3 and 6 weeks to gauge how much weight you would add in the next block.', 2, 2, 7, 5, 90, 1, 1, true, true, false, false);
