INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1009, 'MAPS Anabolic (Pre-Phase) + No BS 6-Pack (Phase 1)', 'maps-anabolic-pre-phase-no-bs-6-pack-phase-1', 'This program combines MAPS Anabolic''s Pre-Phase with Phase 1 of the No BS Six-Pack Formula to build overall muscle strength and enhance core definition. The Pre-Phase focuses on strength and muscle coordination, with 2 foundational workouts per week (1-2 sets, 12-20 reps) and weekly anabolic trigger sessions (10-20 reps). Phase 1 of the No BS Six-Pack program targets abdominal growth with 2 core workouts per week (2-3 sets, 10-20 reps) and 1-2 weekly trigger workouts (15-30 reps). Together, these phases will help you build strength, correct imbalances, and achieve a stronger, more defined core.', 3, 3, 3, 7, 90, 1, 1, true, true, false, false);
