INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1052, 'Home Sessions V2', 'home-sessions-v2', 'An asynchronous, irregular split designed for my summer in VA. Training is every single day but can easily be variable if more rest is needed or something like travel comes up. I find higher frequencies with lower volumes allow me to recover while still pushing each set as hard as possible without fatiguing within a workout. All the movements are pretty simple, yet effective. This isn''t a difficult program to follow because it''s pretty much 0-1 RIR on everything, however it''s a lot of training for a beginner. I am also doing this from my home gym, so it doesn''t matter that I''m only doing relatively little volume per session. If you''re thinking of running this in a commercial gym but have to commute, it might just not be worth it.', 4, 2, 8, 6, 40, 1, 1, true, true, false, false);
