INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1058, 'Hustler Season', 'hustler-season', 'This program is designed for intermediate lifters that already know the basics and have good form but are working to build their overall strength and aesthetics. For people that don’t have a lot of time in their days but still want to improve at the gym. This program seeks to work most of the major muscle groups and their antagonistic pairs. The program’s progression is building up to a one rep max at the end of the 6 week program. The weekly progression of the program is more difficult at the start of the week however, deload is allowed and encouraged by the end of the week. Wake up! It’s Hustler Season!!!', 8, 3, 6, 5, 40, 1, 1, true, true, false, false);
