INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1060, 'Waffle House Strong', 'waffle-house-strong', 'A power-building program from Josh Bryant that uses pyramids to reverse pyramids to build strength and volume.', 2, 2, 7, 6, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1061, 'David Horne''s basic grip routine', 'david-hornes-basic-grip-routine', 'It''s an additional component to add to your existing training to specifically increase grip strength and add some forearm mass. As far as increasing weight goes just increase weight as necessary but remember this is a marathon not a Sprint especially considering if you go too hard and mess up your hands it will affect your other training as well. Also for the two-hand plate pinch as you get heavier a good suggestion would be to put plates onto a t-bar row bar and then hold it that way.', 4, 1, 12, 3, 20, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1062, 'El Santo', 'el-santo', 'Introducing LuchaFit: Unleash the Masked Warrior Within – a workout program inspired by the legendary El Santo Enmascarado. Channel your inner luchador with high-intensity exercises infused with the strength, agility, and resilience of Mexican wrestling. Transform your body and spirit as you embark on a fitness journey that blends the excitement of lucha libre with effective training techniques. Get ready to sweat, grapple, and conquer your fitness goals while embracing the iconic spirit of El Santo!', 8, 1, 8, 4, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1063, 'Kento Nanami Arc Phase 2', 'kento-nanami-arc-phase-2', '9 week fullbody hypertrophy block', 4, 1, 9, 4, 90, 1, 1, true, true, false, false);
