INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1065, 'Garage Strength & Hypertrophy', 'garage-strength-hypertrophy', 'This program is made for beginner to intermediate lifters to progressively gain strength as well as muscle size. Using a double progression with a low to medium-high rep range, weight can be increased on each exercise while doing enough volume to stimulate hypertrophy. The program is also made in mind for the average garage lifter with a barbell and dumbbells doing an Upper/Lower split. Though, if some equipment is unavailable, there will be alternative exercises to use instead', 2, 2, 6, 4, 50, 1, 1, true, true, false, false);
