INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1077, 'RP Hypertrophy 4 Day Upper/Lower', 'rp-hypertrophy-4-day-upperlower', 'This is a general full body hypertrophy orientated workout plan. All reps should be in the 5-30 range. All exercises need to be performed with great technique and control. Each week gets progressively more challenging and it is recommended to stick with movements and rep ranges that allow one to accumulate less fatigue while having maximum stimulus. Exercise time varies from 40-70 minutes depending on the amount of volume and speed one goes through a workout. This program is just a baseline and it is encouraged for individuals to add sets or take away sets based on effectiveness measured by (pump, soreness, recovering before next workout).', 2, 3, 5, 4, 60, 1, 1, true, true, false, false);
