INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1104, 'My personal Training plan', 'my-personal-training-plan', 'This Novice friendly Program is inspired by my past Training experience and exercises I like, it is also inspired by mike mentzers heavy duty Training.', 4, 3, 8, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1105, 'Sigmalifting', 'sigmalifting', 'Candito 6 week template with my own accessories.', 4, 3, 6, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1106, 'Push Pull 4 Days ( liban )', 'push-pull-4-days-liban-', 'This 4-day training program is designed for those lifters who want to build strength, size, and improve muscular balance. The program targets all major muscle groups across the week with a smart push-pull split. Expect progressive overload, balanced volume, and enough recovery to optimize gains. Ideal for those looking to take their physique and performance to the next level', 4, 1, 5, 4, 100, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1107, 'Rat Race', 'rat-race', 'This intermediate lifter program is designed for people who have a busy schedule but still trying to get ripped and athletic. The program is a 3-day upper-lower split that focuses on efficiency, ensuring you can complete your workouts in 45-60 minutes while maintaining intensity and volume for hypertrophy.', 3, 3, 8, 6, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1108, 'Brian Alsruhe''s Conjugate program', 'brian-alsruhes-conjugate-program', 'Conjugate training based on Brian Alsruhe''s program from Neversate', 2, 2, 12, 4, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1109, 'Doug program block 2', 'doug-program-block-2', 'I will update this weekly for you based on the feedback from you. So every week looks the same right now but I will edit them once you complete a week. Once the workouts are complete use the share feature and send them to me. This is meant to go as Day 1 day 2 day 3 day 4 rest day 5 rest. For accessory movements make sure your technique and rest times stay similar to make measurable progress. And then progress them by adding more weight or reps when possible. The app keeps track of everything to make this simple to do.', 4, 3, 5, 5, 80, 1, 1, true, true, false, false);
