INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1169, 'Hybrid Athlete Build Plan', 'hybrid-athlete-build-plan', 'This 4-week hybrid training program is designed to help you build lean muscle mass, increase strength, and improve overall conditioning without sacrificing speed or endurance. It’s perfect for athletes who want to look strong, move fast, and perform at a high level. The program combines traditional resistance training with sprint work, zone 2 cardio, and functional movements to enhance performance and aesthetics at the same time. Each week includes structured strength sessions and smart conditioning work to maximize results and recovery.', 2, 2, 4, 5, 60, 1, 1, true, true, false, false);
