INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1195, 'DirectedbyD Training', 'directedbyd-training', 'This easy to follow training program (combined with a balanced healthy diet) is designed to help you gain and maintain strength while sculpting a good strong core with defined muscles. This program has easy to follow workouts that ensure all muscle groups are serviced with gradually increasing intensity to ensure you achieve the gains without being overwhelmed.', 8, 1, 4, 5, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1196, 'Skanda Strength Protocol', 'skanda-strength-protocol', 'The Skanda Strength Protocol is designed for novices to intermediate lifters who are short on time but still want to achieve a powerful, warrior-like physique. This program is optimized to deliver maximum results in just 3 days a week, efficiently targeting strength development and muscle growth. By combining the essentials of strength training with hypertrophy-focused exercises, the Skanda Strength Protocol helps you build a God-like physique while conquering your fitness goals with precision and intensity. Whether you''re aiming to increase muscle mass, boost strength, or develop a balanced physique, this program provides a time-efficient path to transformation.', 4, 1, 4, 4, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1197, 'vitruvian man', 'vitruvian-man', 'Build hypertrophy for lacking body parts', 3, 3, 5, 7, 80, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1198, '70s Powerlifter - Beginner Modified - Peak phase', '70s-powerlifter---beginner-modified---peak-phase', 'Strength and mass for begginers, using barbells and some isolation, using Alexander Bromley''s 70s Powerlifter program as a base. I am neither a coach or a pro, I made this program for myself and friends. Please make sure you have completed at least one cycle of the base phase before going on to this phase. At the end of this phase, you''ll have a true 1RM which you can then use to complete percentile based programs.', 3, 2, 9, 3, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1199, 'UNKRAUT (3 day full body powerbuilding)', 'unkraut-3-day-full-body-powerbuilding', '„UNKRAUT“ is a 3 times a week full body program inspired by the Texas Method. It‘s designed for people who don‘t have time to go to the gym too often due to work, life or even participating in other sports.', 4, 2, 6, 3, 90, 1, 1, true, true, false, false);
