INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1202, 'Silas'' 4-Day Powerbuilding LPPL Split', 'silas-4-day-powerbuilding-lppl-split', 'For those who have a slower recovery but have very good mind-muscle connection and know their bodies. You will get stronger and more esthetically pleasing through this program. There is a large emphasis that you actually rest on the rest days. It is recommended that each day be paired with 30 minutes of non-vigorous cardio, a 15-minute sauna session, and 15 minutes of stretching afterward.', 2, 2, 5, 4, 70, 1, 1, true, true, false, false);
