INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1210, 'Cut the crap', 'cut-the-crap', 'This program is designed for people who actually want to put in quality work. It doesn''t take 8 plus exercises per workout to build a good physique. In fact I would argue that around half of that is optimal for most people. Which is exactly what this program is designed for. Get in the gym, annihilate the muscles that you want to annihilate. Recover and repeat.', 2, 3, 6, 4, 60, 1, 1, true, true, false, false);
