INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1214, 'Kikito''s Baki Quest V0.2', 'kikitos-baki-quest-v02', 'Personal journey to become God', 4, 2, 8, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1215, 'Buff Booch 1.0', 'buff-booch-10', 'The purpose of this program is to build muscle (hypertrophy) using a structured 4-day push, pull, legs, and arms split with a focus on double progression. By progressively increasing reps and weight, the program aims to enhance strength while taking most sets close to failure for optimal muscle growth. It incorporates a mix of compound and isolation exercises to target all major muscle groups, ensuring balanced development whilst using equipment from a home gym.', 8, 2, 4, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1216, 'Basic Male Lifting Routine', 'basic-male-lifting-routine', 'Originally made for my boyfriend, covers pretty well upper body training and involves some leg work too.', 8, 2, 8, 3, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1217, 'Steve''s training workout', 'steves-training-workout', 'Be stronger than Steve', 4, 2, 8, 3, 120, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1218, 'Chesticular Fortitude', 'chesticular-fortitude', 'This workout is all about unleashing your inner fire and owning every inch of who you are. It’s about feeling the burn, savoring the sweat, and letting your body move in ways that make you feel powerful and free. Each rep is a love letter to yourself, a celebration of the strength and beauty you carry. You’re not just lifting weights—you’re lifting your confidence, your pride, and your spirit. So flex those muscles, feel the rhythm, and let every move be a bold, unapologetic expression of who you are. This is your time to shine, sweat, and sizzle. Stay fierce, stay fabulous.', 4, 3, 4, 6, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1219, 'Full Body General Strength and Fitness', 'full-body-general-strength-and-fitness', 'Getting me stronger.', 8, 2, 8, 4, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1220, '3/4/5 SBD Program', '345-sbd-program', 'A flexible and simple SBD program for those who want to focus on improving their compound lifts. Each week, increase each lift by 5 lbs if all of the target reps are hit the week prior. Similar to 5/3/1, only use 85% of your 1RM to determine your numbers. Week one, start with 85% of your training max (85% of your 1RM) and go from there. This program is designed to run indefinitely. If target reps are not hit, decrease the weight by 10% the next week.', 2, 1, 12, 3, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1221, 'Gains R Us', 'gains-r-us', 'I wanted to try a workout that uses more supersets so I thought this would be a fun change.', 4, 3, 12, 4, 60, 1, 1, true, true, false, false);
