INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1223, 'Th3 Intermediate', 'th3-intermediate', 'Increase strength (1RM) of the back squat, bench press, and deadlift', 2, 3, 8, 4, 70, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1224, 'Dinicolantonio Inspired Workout Program', 'dinicolantonio-inspired-workout-program', '**Dinicolantonio Inspired Workout Program** is a dynamic 4-week training regimen designed to elevate your fitness through a blend of strength, cardio, and mobility workouts. With 24 sessions spread across the month, you''ll engage in high-intensity circuits, strength training, and active recovery days, ensuring a comprehensive approach to fitness. Each workout is crafted to challenge your limits while promoting recovery, making it perfect for those looking to enhance their overall performance. Get ready to push your boundaries and achieve your fitness goals with this structured and effective program!', 4, 3, 4, 6, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1225, '3 steps forward 2 steps back', '3-steps-forward-2-steps-back', 'To get a new 3 rep max and get a horrible back pump from kettlebell deadlifts. When choosing your 1 rep max be conservative. And when finishing the program only add 5 to 20 lbs onto old maxes when running again. Don''t recalculate your 1rm remember slow is fast.', 4, 2, 8, 4, 120, 1, 1, true, true, false, false);
