INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1228, 'MInimalist Training with Biceps and Delt focus', 'minimalist-training-with-biceps-and-delt-focus', 'A minimalist program, hitting Delts and Biceps 3 times a week and all the others major muscle groups 2 times a week', 2, 2, 7, 5, 60, 1, 1, true, true, false, false);
