INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1237, '12 Weeks Booty Gainz Program', '12-weeks-booty-gainz-program', 'build her glutes naturally with strength training', 8, 2, 12, 3, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1238, 'Stank Tanks Training: Vol. 1 - Unleash The Stank', 'stank-tanks-training-vol-1---unleash-the-stank', 'You gotta eat big to get big.  This program is designed for those that want to eat heavy & lift heavy. You''re gonna get a good daily spanking with max effort lifts, and accessory work in the 8-12 rep range, leaving only 1-2 reps left in the tank each set. If you feel like you have more than 1-2 left on EACH SET, then pick up bigger weights! Max weights, minimal rest. Should be done within an hour, and your CNS should be blitzed! If not...#Rule3.', 4, 1, 4, 5, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1239, 'Minimalist Fundamentals', 'minimalist-fundamentals', 'Round out my physique doing compound exercises.', 4, 3, 12, 4, 30, 1, 1, true, true, false, false);
