INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1241, 'Aloittelija ohjelma', 'aloittelija-ohjelma', 'Ohjelman tarkoitus on kasvattaa lihasta ja toimia pohjana tärkeiden sali liikkeiden opettelulle aloittelijalle. Progressio/kehitys tapahtuu double progression tyylillä eli kun liikkeissä rep range on 8-12 aloita painoilla, joilla saat 8 toiston sarjoja, sitten seuraavalla treenillä koita tehdä enemmän toistoja ja kun jossain treenissä saat tehtyä kaikki sarjat 12 toistolla -> lisää painoa niin, että saat taas 8 toiston sarjoja ja jatka samaa metodia. Leuoissa on ainut poikkeus tähän niissä tehdään 3 toiston sarjoja hyvällä tekniikalla lisäten painoa viikottain. Aluksi tehdään 4x3 kehonpainolla/lisäpainolla ensi viikolla 3x3 lisäten painoa sopivasti ja 3 viikolla 2x3 taas lisäten painoa, mutta tekniikan tulee pysyä puhtaana', 2, 2, 3, 3, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1242, 'Godsplit', 'godsplit', 'The purpose of this program is to put in serious work in the gym while gaining strength and size. Put in the work. Reap the Rewards.', 4, 2, 5, 7, 90, 1, 1, true, true, false, false);
