INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1252, 'Daniel’s PPL', 'daniels-ppl', 'A comprehensive strength training program designed to maximize muscle growth and build raw strength through progressive overload. Each workout is structured around key compound lifts—bench press, deadlift, squat, and overhead press—calculated as a percentage of your one-rep max. Over the course of five weeks, the program strategically varies rep ranges and intensities, ensuring continuous progress while incorporating essential recovery periods. Ideal for those who want to improve performance and strength systematically.', 2, 1, 4, 4, 60, 1, 1, true, true, false, false);
