INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1274, 'Goku’s Yardrat saga', 'gokus-yardrat-saga', 'Short 4 week long training in which I experiment more. Born from “Test”.  The idea is seeing if this workout makes me stronger and I look better. Asking the question: does this works? How can I improve on the program? The Yardrat reference is because Goku spent a little bit of time on the planet, and learned a lot from it. Took what he learned, brought it back home and trainer better thanks to it. I’ll try and do a similar thing here', 2, 1, 4, 5, 70, 1, 1, true, true, false, false);
