INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1284, 'The Growth Protocol', 'the-growth-protocol', 'To help intermediate lifters and other advanced athletes get to the next level. Even beginners can use this program providing that they be patent with themselves.', 4, 2, 5, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1285, 'Hypertrophy 225', 'hypertrophy-225', 'This program is designed to build strength across a range of compound lifts using moderate to high rep ranges (3–30 reps), while also progressively increasing strength in accessory and isolation movements. The primary goal is to drive muscle growth (hypertrophy), using strength gains as a key indicator of progress. If only the first set has an RPE listed, it''s because it is used to set the initial load appropriately. Subsequent sets are performed with the same weight, and while they may feel more challenging due to accumulating fatigue, the goal is to complete them with the same load.', 2, 2, 6, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1286, 'upper lower bro', 'upper-lower-bro', 'Doing whatever it takes, right babe?', 4, 2, 6, 5, 70, 1, 1, true, true, false, false);
