INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1288, '3 day strength 2nd', '3-day-strength-2nd', 'Add strength, low volume.', 4, 2, 12, 3, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1289, 'PPSA 70’s Big', 'ppsa-70s-big', 'A throwback to the golden years of STRENGTH TRAINING. Very simple straightforward strength training that is an everyday challenge. The plan is written much like a diary from a very dedicated strength enthusiast. Plan rotates from Press Day, to Leg Day, to Back Day. Huge Deadlift sessions on Day 5,10,15, and 20. A great program for the bodybuilding community, and anyone who is wanting to get very strong and thick.  A very serious plan for the serious lifter.  Plan includes 20 days of Strength Training. The plan is versatile and can be used as a three day, four day, or five day per week program according to your commitment level.', 2, 2, 5, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1290, 'Prisoner Body', 'prisoner-body', 'This Program is designed for Novice-Intermediate lifters who want to ramp up the volume on their upper body and focus on growing the shoulders and arms as well as the abs, everyone says abs are made in the kitchen, but they’re a muscle that can be trained and can grow! This program relaxes a little bit on the volume for the Legs but will maintain squatting strength. You may add exercises to the lower days if you feel like doing so. Enjoy!', 4, 3, 6, 5, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1291, 'Billy’s Strength Program', 'billys-strength-program', 'Get stronger bigger numbers on squat bench deadlift', 8, 2, 8, 3, 90, 1, 1, true, true, false, false);
