INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1302, 'Muscle Building', 'muscle-building', 'For beginner to intermediate lifters without all the fancy equipment. Need dumbbells and a bench, nothing else. Short(er), effective workouts to make the most of your time.', 2, 1, 6, 4, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1303, 'Peak Strength& Hypertrophy 7 week long program.', 'peak-strength-hypertrophy-7-week-long-program', 'By focusing on compound lifts, accessory exercises, and posterior chain development, this program aims to build the strength, muscle mass, and stability required for explosive athlete’s while also preventing injury and improving overall technique in their sport.', 4, 3, 7, 2, 80, 1, 1, true, true, false, false);
