INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1310, '🔥 Upper Body Dominance: 3-Day Growth System 🔥', '-upper-body-dominance-3-day-growth-system-', 'Upper Body Dominance: A science-based 3-day workout plan designed for maximum muscle growth. Featuring supersets, myo-reps, drop sets, and lengthened partials, this program prioritizes upper body hypertrophy while maintaining lower body balance. Perfect for those looking to build strength and size efficiently in just one hour per session. 💪🔥', 2, 2, 6, 3, 60, 1, 1, true, true, false, false);
