INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1313, 'Scion''s full body split', 'scions-full-body-split', 'This program is for those who go to gym 3 times a week. The idea is to have a routine of two main workouts. A and B, where one includes horizontal push combined with vertical pull, and the other one horizontal pull combined with vertical push. On the third week we get to do a complimentary week, which includes exercises we leave out from basic routines. The workout should last 45 min per time.', 8, 1, 6, 3, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1314, 'Conquest', 'conquest', 'This program is purely for fun. Do it on a bulk to look like your favorite Viltrumite warrior.', 2, 1, 10, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1315, 'Hercules Powerbuilding Program', 'hercules-powerbuilding-program', 'Basic program to build strength and muscle without needing fancy gyms or equipment. Rep schemes change weekly to push a range of adaptations and breaks the monotony 5x5 style programs. Not percentage based so enables the lifter to train as hard as possible based on their strength and energy on every given workout without the fear of “missing” reps commonly found it aggressive percentage based programs.', 4, 2, 4, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1316, 'Big n Strong', 'big-n-strong', 'Made this program to hopefully get some people.. you guessed it, Big n Strong. Swap out specific exercises if need be due to equipment or personal choice, but keep movement patterns as similar as possible (ex. Pull-ups subbed for lat pulldowns).', 4, 2, 4, 4, 60, 1, 1, true, true, false, false);
