INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1319, 'Power Matrix', 'power-matrix', 'In the program, lifters perform sets and reps at percentages of their one rep max, based on a chart. If they complete all reps two weeks in a row, they increase the weight and move to the next column of the matrix the following week. If they fail two weeks in a row, they decrease the weight by 10% and work back up. Add in accessories without taking away from main lifts. Accessories should compliment the muscle group worker that day, i.e. Upper/Lower, and remain consistent through the program. Add in an extra day/week of Overhead press or whatever lift needs the most work. CLICK ON THE LINK FOR THE POWER MATRIX CHART https://www.reddit.com/r/powerlifting/s/4tTMvpBrql', 4, 3, 16, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1320, 'Jerma 30min', 'jerma-30min', 'Building initial strength and small muscle gains to increase work capacity', 4, 3, 12, 2, 40, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1321, 'Barbell Bending Barbary', 'barbell-bending-barbary', 'Minimalist strength und muscle building program focused on barbell compound movements plus some key isolation excercises. Full body 3 times per week. Six excercises per day to keep it simple.', 4, 1, 6, 3, 50, 1, 1, true, true, false, false);
