INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1327, 'AX Built for Strength', 'ax-built-for-strength', 'Strength! If that is your primary training goal then this plan delivers without any distractions. This plan''s calendar is 4 days a week and follows an upper/lower split with 2 days on, 1 off, 2 on and 2 off. You will hit your big lifts in multiple rep ranges using percentages of your RM as well as utilizing RPE to dial in the right resistance on any given day in the gym.', 2, 2, 4, 4, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1328, 'Warrior Strength', 'warrior-strength', 'This workout focuses on creating functional strength and a good amount of muscle growth. It can be done by everyone.', 4, 3, 8, 3, 50, 1, 1, true, true, false, false);
