INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1336, 'Iron Press', 'iron-press', 'This setup ensures consistent, long-term gains across all three lifts, which is ideal for lifters who want to specialize in pressing strength without neglecting full powerlifting development. Use 90% of 1RM for Squat, and Deadlift only every cycle.', 8, 1, 5, 5, 120, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1337, 'Hero Build 2.0 PPL', 'hero-build-20-ppl', 'Classic ppl that can be used as is (10 sets per muscle group per week) or you can add another push, pull or legs day to bring volume up. I recommend taking every 3rd day off for recovery.', 4, 2, 6, 3, 40, 1, 1, true, true, false, false);
