INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1339, 'Curvy Body Saves The Day', 'curvy-body-saves-the-day', 'In the quest for a stronger and well-sculpted physique, exercise plays an undeniable role. While conventional wisdom often advocates for a single daily workout, emerging fitness strategies suggest that exercising three times a day could be highly beneficial for enhancing physical strength and achieving a sculpted body. This approach, though intensive, can offer unique advantages when executed properly.', 7, 2, 5, 3, 10, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1340, 'Howey''s Phase One HIT A B', 'howeys-phase-one-hit-a-b', 'A mass gain programme for novice trainers utilising High Intensity Training on an A/B training split.  The last two sets of every exercise are taken to momentary muscle failure except deadlifts and back extensions.', 4, 3, 6, 3, 50, 1, 1, true, true, false, false);
