INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1368, 'Toji Fushiguro Physique - Stage 2', 'toji-fushiguro-physique---stage-2', 'This is stage 2 of Natural Hypertrophy''s Toji Fushiguro program.', 4, 2, 12, 3, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1369, 'Hypertrophy 101', 'hypertrophy-101', 'This program is designed to build strength across a range of compound lifts using moderate to high rep ranges (5–30 reps), while also progressively increasing strength in accessory and isolation movements. The primary goal is to drive muscle growth (hypertrophy), using strength gains as a key indicator of progress. If only the first set has an RPE listed, it''s because it is used to set the initial load appropriately. Subsequent sets are performed with the same weight, and while they may feel more challenging due to accumulating fatigue, the goal is to complete them with the same load.', 4, 1, 6, 3, 60, 1, 1, true, true, false, false);
