INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1439, 'Trainer Steve''s 15', 'trainer-steves-15', 'This 4-week novice-intermediate based program is designed to help increase your muscular strength and size at only 15 minutes per day. This can be a great option if you''re in a busy season of life, but you still want your fitness to be a priority. All exercises are prescribed for using dumbbells due to their accessibility. However, a barbell and/or kettlebell can easily be substituted. Almost all lifts are not programmed as supersets, but they can be, if you need to save more time.', 8, 1, 4, 6, 20, 1, 1, true, true, false, false);
