INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1469, 'Becoming an Athlete', 'becoming-an-athlete', 'This program is for beginners, intermediate, or those that are coming off of injury but still need the stimulus of an athlete. I created this program, when I broke my leg, could lift weights but could not sprint or jump just yet. This program with combination with sprinting and plyometrics 2-3 times a week is as good a program ad any. You can do this workout for as many weeks as needed. If there is demand for more advanced program I will make one.', 4, 1, 4, 3, 80, 1, 1, true, true, false, false);
