INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1472, 'Home Fat Loss Program', 'home-fat-loss-program', 'This beginner level program is made to shed fat for those with slower metabolisms and those who either don’t feel comfortable in a gym or just prefer at home workouts. This program uses body weight focused exercises with light dumbbells to shed fat and increase cardiovascular capacity.', 7, 1, 4, 3, 30, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1473, 'Scion''s big guy program', 'scions-big-guy-program', 'This training focuses on putting more effort in one muscle group at a time. We combine training according to synergy, meaning bench press with triceps, as they tire at the same time. We combine Back training with biceps. Squats with leg and core training.', 4, 2, 4, 3, 50, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1474, 'T2C Triathlon Strength', 't2c-triathlon-strength', 'Injury prevention and strength development for triathletes and endurance athletes.', 8, 3, 8, 2, 60, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1475, 'SBD Strength Upper/Lower', 'sbd-strength-upperlower', 'The purpose of the SBD strength upper/lower program is to increase your strength and muscle mass in the main lifts: squat, bench press, and deadlift. The program follows an upper/lower split, meaning you train your upper body and lower body on separate days. This allows you to train each muscle group twice a week, which is optimal for muscle growth and recovery. The program also includes accessory exercises to target specific muscles and improve your weak points. The SBD strength upper/lower program is a great choice for intermediate and advanced lifters who want to get stronger and bigger. 💪', 2, 3, 1, 5, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1476, 'Powerbulding ODBS', 'powerbulding-odbs', 'Aim for linear increase strength in powerlifting (overhead press, deadlift, bench press and barbell squat) and at the same time, some hypertrophy and isolation', 2, 3, 4, 4, 90, 1, 1, true, true, false, false);
INSERT INTO programs (id, program_name, slug, description, category_id, level_id, duration_weeks, days_per_week, session_duration_minutes, training_split_id, periodization_phase_id, is_active, is_public, is_featured, is_premium) VALUES (1477, 'Atolifts strength through high frequency', 'atolifts-strength-through-high-frequency', 'High volume low intensity week, followed by a high intensity low volume week. If single on second week is easy, increase lift max by 2.5 or 5 kg. If it''s difficult, repeat with same weight. If no lift, reduce max accordingly.', 2, 1, 2, 6, 60, 1, 1, true, true, false, false);
